template <class X>
struct invokeAfterMsg {
    static constexpr std::uint32_t kId = 0xcb9f372du;
    std::int64_t msg_id{};
    X query{};
    using Result = typename X::Result;
    void serialize(TlWriter& tlw) const {
        tlw.write_uint32(kId);
        tlw.write_int64(msg_id);
        query.serialize(tlw);
    }
    static Result read_result(TlReader& rv) { return X::read_result(rv); }
};

template <class X>
struct invokeAfterMsgs {
    static constexpr std::uint32_t kId = 0x3dc4b4f0u;
    std::vector<std::int64_t> msg_ids{};
    X query{};
    using Result = typename X::Result;
    void serialize(TlWriter& tlw) const {
        tlw.write_uint32(kId);
        tl::write_vector(tlw, msg_ids, [&](TlWriter& tlw1276, const auto& e1276) { tlw1276.write_int64(e1276); });
        query.serialize(tlw);
    }
    static Result read_result(TlReader& rv) { return X::read_result(rv); }
};

template <class X>
struct initConnection {
    static constexpr std::uint32_t kId = 0xc1cd5ea9u;
    std::int32_t api_id{};
    std::string device_model{};
    std::string system_version{};
    std::string app_version{};
    std::string system_lang_code{};
    std::string lang_pack{};
    std::string lang_code{};
    std::optional<std::shared_ptr<tl::InputClientProxy>> proxy;
    std::optional<std::shared_ptr<tl::JSONValue>> params;
    X query{};
    using Result = typename X::Result;
    void serialize(TlWriter& tlw) const {
        tlw.write_uint32(kId);
        {
            std::uint32_t flags_v = 0;
            if (proxy.has_value()) flags_v |= (1u << 0);
            if (params.has_value()) flags_v |= (1u << 1);
            tlw.write_uint32(flags_v);
        }
        tlw.write_int32(api_id);
        tlw.write_string(device_model);
        tlw.write_string(system_version);
        tlw.write_string(app_version);
        tlw.write_string(system_lang_code);
        tlw.write_string(lang_pack);
        tlw.write_string(lang_code);
        if (proxy.has_value()) { proxy.value()->serialize(tlw); }
        if (params.has_value()) { params.value()->serialize(tlw); }
        query.serialize(tlw);
    }
    static Result read_result(TlReader& rv) { return X::read_result(rv); }
};

